function projectOut(array $data): never { echo json_encode($data, JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE); exit; }
function projectSchema(PDO $db): void {
    $db->exec("CREATE TABLE IF NOT EXISTS VveGuiProjecten (ProjectID INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, Naam VARCHAR(255) NOT NULL, Status VARCHAR(24) NOT NULL DEFAULT 'groen', StabuCode VARCHAR(32) NULL, MJOPReferentie VARCHAR(10) NULL, Haalbaarheid MEDIUMTEXT NULL, Planning MEDIUMTEXT NULL, Uitvoering MEDIUMTEXT NULL, OpleveringNazorg MEDIUMTEXT NULL, vvegui_modified_at DATETIME NOT NULL, vvegui_modified_by VARCHAR(128) NOT NULL, INDEX idx_project_status (Status), INDEX idx_project_naam (Naam)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $columns=$db->query("SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='VveGuiProjecten'")->fetchAll(PDO::FETCH_COLUMN);
    if(!in_array('StabuCode',$columns,true))$db->exec('ALTER TABLE VveGuiProjecten ADD COLUMN StabuCode VARCHAR(32) NULL AFTER Status');
    if(!in_array('MJOPReferentie',$columns,true))$db->exec('ALTER TABLE VveGuiProjecten ADD COLUMN MJOPReferentie VARCHAR(10) NULL AFTER StabuCode');
    $db->exec("CREATE TABLE IF NOT EXISTS ProjectActiva (ProjectID INT UNSIGNED NOT NULL, ActivaID INT UNSIGNED NOT NULL, PRIMARY KEY (ProjectID,ActivaID), INDEX idx_project_activa (ActivaID)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $db->exec("CREATE TABLE IF NOT EXISTS ProjectRelaties (ProjectID INT UNSIGNED NOT NULL, RelatieID INT UNSIGNED NOT NULL, PRIMARY KEY (ProjectID,RelatieID), INDEX idx_project_relatie (RelatieID)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $db->exec("CREATE TABLE IF NOT EXISTS ProjectDocumenten (ProjectID INT UNSIGNED NOT NULL, DocumentID BIGINT UNSIGNED NOT NULL, PRIMARY KEY (ProjectID,DocumentID), INDEX idx_project_document (DocumentID)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $db->exec("CREATE TABLE IF NOT EXISTS ProjectEmails (ProjectID INT UNSIGNED NOT NULL, EmailBerichtID BIGINT UNSIGNED NOT NULL, PRIMARY KEY (ProjectID,EmailBerichtID), INDEX idx_project_email (EmailBerichtID)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $db->exec("CREATE TABLE IF NOT EXISTS ProjectFotos (FotoID INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, ProjectID INT UNSIGNED NOT NULL, Bestandsnaam VARCHAR(255) NOT NULL, Bestandspad VARCHAR(500) NOT NULL, Mimetype VARCHAR(100) NOT NULL, Bestandsgrootte INT UNSIGNED NOT NULL, vvegui_modified_at DATETIME NOT NULL, vvegui_modified_by VARCHAR(128) NOT NULL, INDEX idx_project_foto (ProjectID)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $db->exec("CREATE TABLE IF NOT EXISTS ProjectActies (ActieID INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, ProjectID INT UNSIGNED NOT NULL, Actie TEXT NOT NULL, Verantwoordelijk VARCHAR(255) NULL, DatumCompleet DATE NULL, Compleet TINYINT(1) NOT NULL DEFAULT 0, vvegui_modified_at DATETIME NOT NULL, vvegui_modified_by VARCHAR(128) NOT NULL, INDEX idx_project_actie (ProjectID,Compleet)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $db->exec("CREATE TABLE IF NOT EXISTS ProjectChecklist (ChecklistID INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, ProjectID INT UNSIGNED NOT NULL, Fase VARCHAR(32) NOT NULL, Criterium VARCHAR(500) NOT NULL, Datum DATE NULL, Compleet TINYINT(1) NOT NULL DEFAULT 0, vvegui_modified_at DATETIME NOT NULL, vvegui_modified_by VARCHAR(128) NOT NULL, INDEX idx_project_checklist (ProjectID,Fase,ChecklistID)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $db->exec("CREATE TABLE IF NOT EXISTS ProjectDocumentDatum (DocumentID BIGINT UNSIGNED NOT NULL PRIMARY KEY, Inhoudsdatum DATE NOT NULL, BevestigdOp DATETIME NOT NULL, BevestigdDoor VARCHAR(128) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
}
function projectRow(PDO $db,int $id): array { $s=$db->prepare('SELECT * FROM VveGuiProjecten WHERE ProjectID=?');$s->execute([$id]);$r=$s->fetch();if(!$r)throw new RuntimeException('Project niet gevonden.');return $r; }
function projectData(PDO $db,int $id): array {
    $row=projectRow($db,$id);
    $s=$db->prepare('SELECT p.ActivaID,a.Naam FROM ProjectActiva p JOIN Activa a ON a.ActivaID=p.ActivaID WHERE p.ProjectID=? ORDER BY a.Naam');$s->execute([$id]);$assets=$s->fetchAll();
    $s=$db->prepare("SELECT p.RelatieID,COALESCE(NULLIF(TRIM(r.naam),''),NULLIF(TRIM(r.alias),''),CONCAT('Relatie ',p.RelatieID)) AS Naam FROM ProjectRelaties p JOIN relations r ON r.relatie_id=p.RelatieID WHERE p.ProjectID=? ORDER BY Naam");$s->execute([$id]);$relations=$s->fetchAll();
    $s=$db->prepare('SELECT p.DocumentID,d.Titel,d.OrigineleNaam,d.Mimetype,v.Inhoudsdatum FROM ProjectDocumenten p JOIN DocumentBibliotheek d ON d.DocumentID=p.DocumentID LEFT JOIN ProjectDocumentDatum v ON v.DocumentID=d.DocumentID WHERE p.ProjectID=? AND d.VerwijderdOp IS NULL ORDER BY d.Titel');$s->execute([$id]);$documents=$s->fetchAll();
    $s=$db->prepare('SELECT p.EmailBerichtID,e.Subject,e.Sender,e.SentAt FROM ProjectEmails p JOIN EmailBerichten e ON e.EmailBerichtID=p.EmailBerichtID WHERE p.ProjectID=? ORDER BY e.SentAt DESC');$s->execute([$id]);$emails=$s->fetchAll();
    $s=$db->prepare('SELECT FotoID,Bestandsnaam,Mimetype FROM ProjectFotos WHERE ProjectID=? ORDER BY FotoID DESC');$s->execute([$id]);$photos=$s->fetchAll();
    $s=$db->prepare('SELECT ActieID,Actie,Verantwoordelijk,DatumCompleet,Compleet FROM ProjectActies WHERE ProjectID=? ORDER BY Compleet,ActieID DESC');$s->execute([$id]);$actions=$s->fetchAll();
    $s=$db->prepare('SELECT ChecklistID,Fase,Criterium,Datum,Compleet FROM ProjectChecklist WHERE ProjectID=? ORDER BY ChecklistID');$s->execute([$id]);$checklist=$s->fetchAll();
    return ['ok'=>true,'project'=>$row,'assets'=>$assets,'relations'=>$relations,'documents'=>$documents,'emails'=>$emails,'photos'=>$photos,'actions'=>$actions,'checklist'=>$checklist];
}
